/**
 * Shared column builders and SQL fragments for the Drizzle schema.
 *
 * Conventions (D-37):
 * - Table and column names are snake_case (drizzle `casing: 'snake_case'`),
 *   TypeScript properties are camelCase.
 * - Primary keys are text ids generated by Postgres (`gen_random_uuid()::text`)
 *   unless the caller supplies one (sample fixtures use readable ids).
 * - Timestamps are `timestamptz(3)` mapped to JavaScript `Date`.
 */
import { sql, type SQL } from 'drizzle-orm';
import { text, timestamp, type AnyPgColumn } from 'drizzle-orm/pg-core';

/** Text primary key with a database-side UUID default. */
export const idColumn = () =>
  text().primaryKey().default(sql`gen_random_uuid()::text`);

/** `timestamptz(3)` column. */
export const ts = () => timestamp({ withTimezone: true, precision: 3, mode: 'date' });

/** `created_at` with a `now()` default. */
export const createdAt = () => ts().defaultNow().notNull();

/** `updated_at` with a `now()` default, refreshed on every Drizzle update. */
export const updatedAt = () =>
  ts()
    .defaultNow()
    .notNull()
    .$onUpdate(() => new Date());

/** Non-null `text[]` defaulting to an empty array. */
export const textArray = () =>
  text()
    .array()
    .notNull()
    .default(sql`'{}'::text[]`);

/**
 * Row-level-security predicate for tenant-scoped tables [D-19, D-37].
 *
 * The API sets `app.current_org_id` with `set_config(..., true)` inside a
 * transaction (`DbService.withOrgScope`). When the setting is absent or empty
 * the connection is in "system" context and every row is visible: principal
 * loading, seeding and background jobs run that way. When it is set, only rows
 * of that organization are visible or writable.
 *
 * Pass `nullable: true` for columns such as `grants.scope_org_id` where NULL
 * means platform-wide: those rows stay visible in every tenant context.
 */
export function tenantPredicate(
  orgIdColumn: AnyPgColumn,
  opts: { nullable?: boolean } = {},
): SQL {
  const current = sql`current_setting('app.current_org_id', true)`;
  const unscoped = sql`coalesce(${current}, '') = ''`;
  const match = sql`${orgIdColumn} = ${current}`;
  return opts.nullable
    ? sql`(${unscoped} OR ${orgIdColumn} IS NULL OR ${match})`
    : sql`(${unscoped} OR ${match})`;
}

/**
 * Row-level-security predicate for tables that reach their organization only
 * through a join (legacy community tables, the org-unit closure table). The
 * caller supplies the correlated `EXISTS` body as raw SQL; it must compare the
 * joined organization column with `current_setting('app.current_org_id', true)`
 * and correlate on the outer table's columns by their qualified names, for
 * example `"posts"."channel_id"`.
 *
 * Unscoped (system-context) connections see every row, exactly as
 * {@link tenantPredicate}.
 */
export function tenantPredicateVia(existsBody: string): SQL {
  const current = sql`current_setting('app.current_org_id', true)`;
  const unscoped = sql`coalesce(${current}, '') = ''`;
  return sql`(${unscoped} OR EXISTS (${sql.raw(existsBody)}))`;
}

/** SQL text of the tenant setting, for {@link tenantPredicateVia} bodies. */
export const CURRENT_ORG_SETTING = "current_setting('app.current_org_id', true)";
